        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/Antonin_Artaud", Text = "J'ai pour me guérir du jugement des autres toute la distance qui me sépare de moi.", Author = "Antonin Artaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Antonin_Artaud", Text = "Un homme se possède par éclaircies, et même quand il se possède, il ne s'atteint pas tout à fait.", Author = "Antonin Artaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Antonin_Artaud", Text = "Une grande ferveur pensante et surpeuplée portait mon moi comme un abîme plein.", Author = "Antonin Artaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Antonin_Artaud", Text = "Une fatigue de commencement du monde, la sensation de son corps à porter, un sentiment de fragilité incroyable, et qui devient une brisante douleur, un état d'engourdissement une espèce d'engourdissement localisé à la peau, qui n'interdit aucun mouvement mais change le sentiment interne d'un membre, et donne à la simple station verticale le prix d'un effort victorieux.", Author = "Antonin Artaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Antonin_Artaud", Text = "Le soleil a comme un regard. Mais un regard qui regarderait le soleil. Le regard est un cône qui se renverse sur le soleil. Et tout l'air est comme une musique figée, mais une vaste, profonde musique, bien maçonnée et secrète, et pleine de ramifications congelées.", Author = "Antonin Artaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Antonin_Artaud", Text = "L'air autour de la montagne est sonore, pieux, légendaire, interdit. L'accès de la montagne est interdit. La montagne a bien sa place dans l'âme. Elle est l'horizon d'un quelque chose qui recule sans cesse. Elle donne la sensation de l'horizon éternel.", Author = "Antonin Artaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Antonin_Artaud", Text = "Messieurs les dictateurs de l'école pharmaceutique de France, vous êtes des cuistres rognés : il y a une chose que vous devriez mieux mesurer ; c'est que l'opium est cette imprescriptible chose et impérieuse substance qui permet de rentrer dans la vie de leur âme à ceux qui ont eu le malheur de l'avoir perdue.", Author = "Antonin Artaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Antonin_Artaud", Text = "[...] de cette minute d'erreur il me reste le sentiment d'avoir ravi à l'inconnu quelque chose de réel. Je crois à des conjurations spontanées.", Author = "Antonin Artaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Antonin_Artaud", Text = "Certes je fais encore (mais pour combien de temps ?) ce que je veux de mes membres, mais voilà longtemps que je ne commande plus à mon esprit, et que mon inconscient tout entier me commande avec des impulsions qui viennent du fond de mes rages nerveuses et du tourbillonnement de mon sang. Images pressées et rapides, et qui ne prononcent à mon esprit que des mots de colère et de haine aveugle, mais qui passent comme des coups de couteau ou des éclairs dans un ciel engorgé.", Author = "Antonin Artaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Antonin_Artaud", Text = "Il me parle de Narcissisme, je lui rétorque qu'il s'agit de ma vie. j'ai le culte non pas du moi mais de la chair. Toutes les choses ne me touchent qu'en tant qu'elles affectent ma chair, qu'elles coïncident avec elle, et à ce point même où elles l'ébranlent, pas au-delà.", Author = "Antonin Artaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Antonin_Artaud", Text = "On a beau me dire que c'est en moi ce coupe-gorge, je participe à la vie, je représente la fatalité qui m'élit.", Author = "Antonin Artaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Antonin_Artaud", Text = "Quand nous reverrons-nous ? Quand le goût terreux de tes lèvres viendra-t-il à nouveau frôler l'anxiété de mon esprit ? La terre est comme un tourbillon de lèvres mortelles. La vie creuse devant nous le gouffre de toutes les caresses qui ont manqué. Qu'avons-nous à faire auprès de nous de cet ange qui n'a pas su se montrer ?", Author = "Antonin Artaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Antonin_Artaud", Text = "Elle a des mains qui entourent les livres de leurs cartilages de miel. Elle a des seins en viande crue, si petite, dont la pression donne la folie ; elle a des seins en dédales de fil. Elle a une pensée toute à moi, une pensée insinuante et retorse qui se déroule comme d'un cocon. Elle a une âme.", Author = "Antonin Artaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Antonin_Artaud", Text = "Là où ça sent la merde\nça sent l'être.", Author = "Antonin Artaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Antonin_Artaud", Text = "On a fait descendre à ma sensibilité depuis dix ans les marches des plus monstrueux sarcophages., du monde encore inopéré des morts et des vivants qui ont voulu (et au moins où nous en sommes c'est par vice) qui ont voulu vivre morts, mais je me serai tout simplement évité d'être malade et avec moi tout un monde qui est tout ce que je connais.", Author = "Antonin Artaud" },
        };
